#include "mindguard/static.hpp"

#include <chrono>
#include <cstdint>
#include <iostream>
#include <span>

int main() {
  constexpr std::uint64_t iterations = 100;
  std::uint64_t checksum = 0;
  const auto started = std::chrono::steady_clock::now();
  for (std::uint64_t index = 0; index < iterations; ++index) {
    MG_WITH_BYTES("", [&](std::span<const std::uint8_t> value) {
      if (value.size() != 4096U) mindguard::detail::__mindguard_fail();
      checksum += value[static_cast<std::size_t>(index) % value.size()];
    });
  }
  const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::steady_clock::now() - started).count();
  std::cout << elapsed / static_cast<std::int64_t>(iterations) << ' ' << checksum << '\n';
}
